components.css:
.ds-chip { display: inline-flex; align-items: center; gap: 0.5rem; min-height: 3rem; padding: 0.65rem 1.15rem; border-radius: 999px; border: 1.5px solid #f2c14e; background: transparent; color: #f2c14e; font: 650 1rem/1 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; text-decoration: none; cursor: pointer; transition: background-color 0.2s cubic-bezier(0.16,1,0.3,1), transform 0.2s cubic-bezier(0.16,1,0.3,1); }
.ds-chip:hover { background: #1b324b; }
.ds-chip:active { transform: scale(0.97); }
.ds-chip:focus-visible { outline: 3px solid #f2c14e; outline-offset: 3px; }

.ds-chip { display: inline-flex; align-items: center; gap: 0.5rem; min-height: 3rem; padding: 0.65rem 1.15rem; border-radius: 999px; border: 1.5px solid #f2c14e; font: 650 1rem/1 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; text-decoration: none; cursor: pointer; transition: background-color 0.2s cubic-bezier(0.16,1,0.3,1), transform 0.2s cubic-bezier(0.16,1,0.3,1); }
.ds-chip--primary { background: #f2c14e; color: #122438; border-color: #f2c14e; box-shadow: 0 0.5rem 1.25rem -0.5rem rgba(0,0,0,0.55); }
.ds-chip--primary:hover { background: #f6cf6f; }
.ds-chip--primary:active { transform: scale(0.97); }
.ds-chip--primary:focus-visible { outline: 3px solid #faf6ee; outline-offset: 3px; }
.ds-ico { width: 1.25rem; height: 1.25rem; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.ds-tabs { display: flex; gap: 0.25rem; overflow-x: auto; scrollbar-width: none; padding: 0.6rem 0; }
.ds-tabs::-webkit-scrollbar { display: none; }
.ds-tab { flex: none; padding: 0.4rem 0.85rem; border-radius: 999px; background: #1b324b; color: #faf6ee; font: 600 0.875rem/1.4 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; text-decoration: none; transition: background-color 0.2s cubic-bezier(0.16,1,0.3,1), color 0.2s cubic-bezier(0.16,1,0.3,1); }
.ds-tab:hover, .ds-tab[aria-current="true"] { background: #f2c14e; color: #122438; }
.ds-tab:focus-visible { outline: 3px solid #f2c14e; outline-offset: 3px; }

.ds-bill { background: #1b324b; width: min(100%, 30rem); color: #faf6ee; border: 1px solid rgba(250,246,238,0.14); border-radius: 1.5rem; padding: clamp(1rem, 3vw, 1.75rem); box-shadow: 0 1.5rem 3rem -1.5rem rgba(0,0,0,0.5); }
.ds-bill__label { margin: 0 0 0.75rem; display: flex; align-items: center; gap: 0.4rem; color: #f2c14e; font: 650 0.875rem/1.4 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; }
.ds-bill__rows { border-top: 2px solid #faf6ee; padding-top: 0.25rem; }
.ds-row { border-bottom: 1px solid rgba(250,246,238,0.14); }
.ds-row summary { list-style: none; cursor: pointer; display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; padding: 1rem 0.25rem; min-height: 3rem; }
.ds-row summary::-webkit-details-marker { display: none; }
.ds-row__name { font: 650 clamp(1.05rem, 2.4vw, 1.25rem)/1.3 "Bricolage Grotesque", ui-sans-serif, system-ui, sans-serif; letter-spacing: -0.01em; display: inline-flex; align-items: center; gap: 0.5rem; flex: 1 1 auto; min-width: 0; }
.ds-row__price { font: 700 clamp(1.15rem, 2.8vw, 1.5rem)/1 "Bricolage Grotesque", ui-sans-serif, system-ui, sans-serif; color: #f2c14e; white-space: nowrap; text-align: right; font-variant-numeric: tabular-nums; flex: none; }
.ds-row__price small { display: block; font: 500 0.75rem/1.4 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; color: #a9b8c9; }
.ds-row[open] .ds-row__name, .ds-row:has(.ds-tag) .ds-row__name { color: #f2c14e; }
.ds-row ul { margin: 0 0 1.1rem; padding: 0 0.25rem 0 2.6rem; color: #faf6ee; max-width: 60ch; font: 400 1.0625rem/1.55 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; }
.ds-row li::marker { color: #f2c14e; }
.ds-tag { font: 700 0.75rem/1 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; background: #f2c14e; color: #122438; padding: 0.3rem 0.55rem; border-radius: 999px; }
.ds-ico { width: 1rem; height: 1rem; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }

.ds-composer { display: grid; gap: 0.75rem; padding: 0.75rem; border-radius: 1.75rem; background: #0d1b2b; border: 1px solid rgba(250,246,238,0.14); max-width: 40rem; }
.ds-field { box-sizing: border-box; width: 100%; min-height: 3.25rem; padding: 0.8rem 1.25rem; border-radius: 999px; border: 1.5px solid #24405e; background: #1b324b; color: #faf6ee; font: 500 1.0625rem/1.4 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; transition: border-color 0.2s cubic-bezier(0.16,1,0.3,1); }
.ds-field::placeholder { color: #9fb0c4; }
.ds-field:focus { outline: none; border-color: #f2c14e; }
.ds-want { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.ds-radio { position: relative; }
.ds-radio input { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: pointer; }
.ds-radio span { display: inline-flex; align-items: center; min-height: 2.75rem; padding: 0.5rem 1rem; border-radius: 999px; border: 1.5px solid #24405e; color: #faf6ee; font: 600 0.9375rem/1.4 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; transition: background-color 0.2s cubic-bezier(0.16,1,0.3,1), color 0.2s cubic-bezier(0.16,1,0.3,1); }
.ds-radio input:checked + span { background: #faf6ee; color: #122438; border-color: #faf6ee; }
.ds-radio input:focus-visible + span { outline: 3px solid #f2c14e; outline-offset: 2px; }
.ds-send { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.ds-sendbtn { display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem; min-height: 3rem; padding: 0.65rem 1.2rem; border-radius: 999px; border: 1.5px solid #f2c14e; background: transparent; color: #f2c14e; font: 650 1rem/1 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; cursor: pointer; transition: background-color 0.2s cubic-bezier(0.16,1,0.3,1), transform 0.2s cubic-bezier(0.16,1,0.3,1); }
.ds-sendbtn:hover { background: #1b324b; }
.ds-sendbtn:active { transform: scale(0.97); }
.ds-sendbtn--primary { background: #f2c14e; color: #122438; flex: 1 1 12rem; }
.ds-sendbtn--primary:hover { background: #f6cf6f; }
.ds-sendbtn:focus-visible { outline: 3px solid #f2c14e; outline-offset: 3px; }
.ds-ico { width: 1.25rem; height: 1.25rem; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }

.ds-sample { margin: 0; display: grid; gap: 0.7rem; width: 18rem; }
.ds-sample__frame { display: grid; place-items: center; aspect-ratio: 4 / 5; border-radius: 1rem; background: #24405e; border: 1px dashed rgba(250,246,238,0.24); color: #a9b8c9; box-shadow: 0 1.25rem 2.5rem -1.25rem rgba(0,0,0,0.6); overflow: hidden; font: 600 0.75rem/1 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; letter-spacing: 0.02em; transition: transform 0.6s cubic-bezier(0.16,1,0.3,1); }
.ds-sample:hover .ds-sample__frame { transform: scale(1.03); }
.ds-recipe { display: grid; gap: 0.1rem; padding: 0 0.25rem; font: 400 0.9375rem/1.45 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; color: #a9b8c9; }
.ds-recipe__name { font: 700 1.125rem/1.25 "Bricolage Grotesque", ui-sans-serif, system-ui, sans-serif; color: #faf6ee; letter-spacing: -0.01em; }
.ds-recipe__goal { color: #faf6ee; }
